+  public func resolveDetail(_ action: DetailAction, from scope: DetailScope?) -> DetailResolution? {
+    guard let scope, detailScope == scope, case let .detail(surface) = route else { return nil }
+    switch action {
+    case let .checklist(action, id):
+      guard surface != .entries else { return nil }
+      return .task(.checklist(action, id))
+    case let .move(offsets, destination):
+      guard surface == .nativeList else { return nil }
+      let order = workspace.tasks(for: scope.projectID).map(\.id)
+      guard let last = offsets.last, last < order.count, (0...order.count).contains(destination)
+      else { return nil }
+      var reordered = order.enumerated().filter { !offsets.contains($0.offset) }.map(\.element)
+      let insertion = destination - offsets.count(in: 0..<destination)
+      reordered.insert(contentsOf: offsets.map { order[$0] }, at: insertion)
+      return .task(.reorder(reordered))
+    case let .document(action):
+      switch action {
+      case let .checklist(intent, id):
+        return resolveDetail(.checklist(intent, id), from: scope)
+      case let .turn(records, direction):
+        return .page(records, direction)
+      case let .control(control):
+        switch control {
+        case .report, .addTask: guard surface != .entries else { return nil }
+        case .showEntries: guard surface == .tasks else { return nil }
+        case .showTasks: guard surface == .entries else { return nil }
+        case .addEntry: guard surface != .tasks else { return nil }
+        case .queue: guard surface != .nativeList else { return nil }
+        }
+        return .control(control)
+      case let .record(control):
+        guard surface != .tasks, let detail = detail() else { return nil }
+        if let id = ProjectDetailControl.draftTarget(control) {
+          return detail.drafts.first { $0.id == id }.map(DetailResolution.draft)
+        }
+        guard surface == .nativeList else { return nil }
+        return detail.entries.first { ProjectDetailControl.entryID($0.id) == control }
+          .map(DetailResolution.entry)
+      }
+    }
   }

