import FieldLogFeatures
import FieldLogModels
import Foundation
import MixerApple
import MixerUI

@MainActor enum ProgressReplay {
  private struct Failure: Error {
    let surface: String
    let expected: String
    let actual: String?
  }

  static func check(baseline: Bool) throws {
    let projectID = UUID()
    let now = Date(timeIntervalSinceReferenceDate: 200)
    for total in [1, 2] {
      var workspace = Workspace(id: UUID(), createdAt: now)
      workspace.projects = [Project(id: projectID, title: "Inspection", createdAt: now)]
      workspace.tasks = (0..<total).map { index in
        WorkTask(id: UUID(), projectID: projectID, title: "Valve \(index)",
                 responsible: "Inspector", position: index, updatedAt: now)
      }
      for completed in [0, 1] {
        if completed == 1 {
          try workspace.toggleTask(workspace.tasks[0].id, now: now)
        }
        for (label, surface, expanded) in [
