private struct Failure: Error { let check: String }

private func check(_ expression: @autoclosure () throws -> Bool, _ label: String) throws {
  if try !expression() { throw Failure(check: label) }
}

private func require<T>(_ value: T?, _ label: String) throws -> T {
  guard let value else { throw Failure(check: label) }
  return value
}

private func refuses(_ label: String, _ operation: () throws -> Void) throws {
  do { try operation() } catch { return }
  throw Failure(check: "accepted " + label)
}

@MainActor private final class Surface: AndroidUINativeSurface {
  let profile = AndroidUIProfile.measuredMultilineLongNotesV4
  var capabilities: AndroidUICapabilities { profile.capabilities }
  private(set) var owner: UUID?
  private(set) var document: UIDocument?
  private(set) var packet: Data?
  private(set) var installed = 0

  func activate(owner: UUID) throws {
    try check(self.owner == nil, "second Android owner")
    self.owner = owner
  }

  func install(_ frame: AndroidUIFrame) throws {
    try check(frame.owner == owner && frame.profile == profile, "installed frame scope")
    let packet = try require(JSONSerialization.jsonObject(with: frame.packet) as? [String: Any], "frame packet")
    let bytes = try JSONSerialization.data(withJSONObject: require(packet["document"], "packet document"))
