      supportedTextFieldAxes: profile.capabilities.textFieldAxes, textValuePolicy: profile.textValuePolicy))
    self.packet = frame.packet
    installed += 1
  }

  func revoke(owner: UUID) {
    precondition(owner == self.owner)
    self.owner = nil
    document = nil
  }
}

