@main struct QueueReplay {
  private static let first = UUID(uuidString: "A1000000-0000-4000-8000-000000000001")!
  private static let second = UUID(uuidString: "A1000000-0000-4000-8000-000000000002")!

  @MainActor static func main() async throws {
    let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
    let mode = CommandLine.arguments[2]
    let apple = root.appendingPathComponent("apple")
    let android = root.appendingPathComponent("android")
    let store = android.appendingPathComponent("FieldLog")
    if mode != "cold" {
