        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try bytes.write(to: directory.appendingPathComponent("workspace.json"))
      }
    }
    let appleInput = try Disk(apple)
    let androidInput = try Disk(store)
    let repo = try WorkspaceRepository(directory: apple)
    let model = WorkspaceModel(repository: repo)
    await model.open()
    if mode == "live" {
      let picker = ProjectPickerPresentation(in: try require(model.workspace, "Apple workspace"), query: "north")
      try check(Array(picker.rows.map(\.id)) == [second], "native picker retained site search")
      model.restoreProject(second)
      await model.flush()
