        "native picker selection intentionally persisted")
    }
    let selected = mode == "live" || mode == "cold" ? second : first
    try check(model.presentation?.projectID == selected && model.presentation?.route == .detail(.nativeList),
      "Apple selected project route")
    let appleBefore = try Disk(apple)
    let androidBefore = try Disk(store)
    let workspace = try require(model.workspace, "Apple open")
    let expected = workspace.outbox.reversed().map { "pending." + $0.idempotencyKey }
    try check(expected.count == 26, "exact queue fixture")

    let pending = PendingChangesNativeHost()
    model.show(.pendingChanges)
    pending.display(try require(model.presentation, "pending state"))
    let appleFrame = try require(pending.frame, "Apple first queue frame")
    try assertPage(appleFrame.snapshot.document, index: 0, expected: Array(expected.prefix(20)), footer: false)
    try check(appleFrame.dates.count == 20, "Apple first page dates")
    let appleNext = try appleEvent(appleFrame, "queue.next")
    func appleActivate(_ frame: PendingChangesNativeHost.Frame, _ event: UIEventEnvelope) throws {
      let current = try require(model.presentation, "Apple current presentation")
      model.acceptPending(try pending.activate(event, owner: frame.owner, presentation: current))
    }
    try refuses("foreign Apple owner") {
      _ = try pending.activate(appleNext, owner: UUID(), presentation: require(model.presentation, "Apple current"))
    }

    let surface = Surface()
    let app = try await PublicAndroidApplication(surface: surface, selectedProfile: surface.profile.rawValue, directory: android)
    let androidDetail = try require(surface.document, "Android detail")
