    let androidFrame = try require(surface.document, "installed Android queue")
    let androidPacket = try require(surface.packet, "first Android queue packet")
    try androidPacket.write(to: root.appendingPathComponent(mode + "-first.packet.json"))
    try assertPage(androidFrame, index: 0, expected: Array(expected.prefix(20)), footer: true)
    let originalNext = try wire(app, "queue.next")
    let owner = try require(surface.owner, "installed Android owner")
    try refuses("foreign Android owner") { try app.sendBatch(owner: UUID(), originalEnvelopes: originalNext) }
    try refuses("Apple disabled previous") { try appleActivate(appleFrame, appleEvent(appleFrame, "queue.previous")) }
    try refuses("Android disabled previous") { try send(app, "queue.previous") }

    switch mode {
    case "live":
      try appleActivate(appleFrame, appleNext)
      try app.sendBatch(owner: owner, originalEnvelopes: originalNext)
      try require(surface.packet, "proposed Android queue page").write(
        to: root.appendingPathComponent("live-proposed.packet.json"))
      let applePageTwo = try require(pending.frame, "Apple second queue frame")
      try assertPage(applePageTwo.snapshot.document, index: 1, expected: Array(expected.suffix(6)), footer: false)
      try assertPage(require(surface.document, "Android page two"), index: 1, expected: Array(expected.suffix(6)), footer: true)
      try check(applePageTwo.dates.count == 6, "Apple second page dates")
      try refuses("Apple old revision") { try appleActivate(applePageTwo, appleNext) }
      try refuses("Android old revision") { try app.sendBatch(owner: owner, originalEnvelopes: originalNext) }
      try refuses("Apple disabled next") { try appleActivate(applePageTwo, appleEvent(applePageTwo, "queue.next")) }
