      try assertPage(reopenedApple.snapshot.document, index: 1, expected: Array(expected.suffix(6)), footer: false)

      try send(app, "workspace.entries")
      try check(app.presentation.entryState != nil, "Android project queue enters new editor")
      try send(app, "workspace.queue")
      try assertPage(require(surface.document, "Android returned queue"), index: 1,
        expected: Array(expected.suffix(6)), footer: true)
      try send(app, "workspace.back")
      try send(app, "workspace.queue")
      try send(app, "workspace.entries")
      try check(app.presentation.entryState != nil, "Android project queue reopens existing editor")
      try send(app, "workspace.queue")
      try assertPage(require(surface.document, "Android returned queue again"), index: 1,
        expected: Array(expected.suffix(6)), footer: true)
      print("LIVE exact 20+6 newest-first rows, labels and IDs; tab ownership and queue page survive route return; Apple picker search and persisted selection")
    case "denied", "preflight":
      let installs = surface.installed
      try refuses("Apple shared \(mode)") { try appleActivate(appleFrame, appleNext) }
      try refuses("Android shared \(mode)") { try app.sendBatch(owner: owner, originalEnvelopes: originalNext) }
      try check(pending.frame?.snapshot.document == appleFrame.snapshot.document && model.presentation?.pendingPage == 0 &&
        surface.document == androidFrame && surface.packet == androidPacket && surface.installed == installs, "refusal left both frames and page intact")
      try require(surface.packet, "retained Android packet").write(
        to: root.appendingPathComponent(mode + "-retained.packet.json"))
      print("CONTROL \(mode) refused both original actions with no replacement frame")
    case "cold":
      try check(Disk(apple) == appleInput && Disk(store) == androidInput, "fresh process performed no writes")
      print("COLD Apple restores selected project, Android opens its existing first project, and both start their queue on page one")
    default: throw Failure(check: "unknown run mode")
    }
    await model.flush()
    try await app.settle()
    await app.close()
    await repo.close()
    try check(Disk(apple) == appleBefore && Disk(store) == androidBefore, "browsing preserved both file bytes, inode and mtime")
    print("DISK workspace bytes, inode, and mtime unchanged on both platforms while browsing")
  }

  private static func assertPage(_ document: UIDocument, index: Int, expected: [String], footer: Bool) throws {
    let sections = try require(document.root.children.first?.children, "queue sections")
    let summary = try require(sections.first, "queue summary")
    let body = try require(sections.last, "queue contents")
    let position = index == 0 ? "Page 1 of 2 · Changes 1–20 of 26 · Newest first" :
      "Page 2 of 2 · Changes 21–26 of 26 · Newest first"
    try check(document.root.properties["title"]?.string == "On device" &&
      summary.children.first?.properties["text"]?.string == "Your records are saved locally" &&
      body.properties["title"]?.string == "Pending changes (26)" &&
      body.children.first?.properties["text"]?.string == position, "visible queue labels")
    try check(body.children.filter { $0.id.hasPrefix("pending.") }.map(\.id) == expected,
      "exact ordered queue row identities")
    let buttons = summary.children.filter { $0.kind == .button }
    try check(buttons.map { $0.properties["accessibilityIdentifier"]?.string } ==
      (footer ? ["workspace-tasks", "workspace-entries"] : []), "surface controls and accessibility IDs")
  }

  private static func appleEvent(_ frame: PendingChangesNativeHost.Frame, _ node: String) throws -> UIEventEnvelope {
    UIEventEnvelope(revision: frame.snapshot.document.revision,
      identity: try require(frame.snapshot.identity(for: node), "Apple queue node " + node), event: .activate)
  }

  @MainActor private static func wire(_ app: PublicAndroidApplication, _ node: String) throws -> Data {
    let frame = app.presentation.snapshot
    let original = UIEventEnvelope(revision: frame.document.revision,
      identity: try require(frame.identity(for: node), "Android node " + node), event: .activate)
    return try JSONEncoder().encode([original])
  }

  @MainActor private static func send(_ app: PublicAndroidApplication, _ node: String) throws {
    try app.sendBatch(owner: require(app.host.owner, "Android owner"), originalEnvelopes: wire(app, node))
  }
}

