  private static func verify(_ saved: Workspace, initial: Workspace, time: ClosedRange<Date>,
    at directory: URL, label: String
  ) throws -> Data {
    try check(saved.outbox.count == initial.outbox.count + 1, label + " exactly one outbox row")
    let actual = try require(saved.outbox.last, "outbox row")
    try check(!initial.outbox.contains { $0.id == actual.id } && time.contains(actual.createdAt),
      label + " new outbox identity and transaction time")
    var expected = initial
    expected.revision += 1
    expected.tasks.swapAt(19, 20)
    for index in expected.tasks.indices {
      expected.tasks[index].position = index
      expected.tasks[index].updatedAt = actual.createdAt
    }
    // Persistence preserves array storage order, separately from display positions.
    expected.tasks.swapAt(19, 20)
    var row = actual
    row.kind = .taskOrderChanged
    row.recordID = projectID
    row.revision = expected.revision
    expected.outbox.append(row)
    let exact = try encode(expected)
    let disk = try Disk(directory)
    try check(saved == expected && disk.bytes == exact, label + " exact workspace and outbox bytes")
    print("\(label)_EXACT workspace=\(hash(exact)) outbox=\(hash(try encode(row)))")
    for index in expected.tasks.indices { expected.tasks[index].updatedAt = fixedDate }
    expected.outbox[expected.outbox.count - 1].createdAt = fixedDate
    expected.outbox[expected.outbox.count - 1].id = projectID
    return try encode(expected)
  }

