             }
         }
         if actions.count == 1, let action = actions.first, action.event == .activate, action.value == .null {
-            if presentation.route == .pendingChanges, let pending = PendingChangesAction(action) {
-                switch pending {
-                case .entries:
-                    try openEntries()
-                case .tasks:
-                    try navigate(to: .detail(.tasks))
-                case .previous, .next:
-                    guard let direction = pending.direction else { throw PublicHostError.action }
