     private func install(_ next: WorkspacePresentation) throws {
         let (updated, frame) = try render(state, presentation: next, feedback: changeFeedback, failure: changeFailure)
         presentation = next
@@ -812,9 +805,8 @@ public enum ReportShareResult: Sendable { case opened, closed, unavailable }
                 photoPending: photoPending, photoMessage: photoMessage, photoBusy: photoBusy, reportPending: reportPending)
