import FieldLogFeatures
import FieldLogModels
import FieldLogStorage
import Foundation

struct ReplayFailure: Error, CustomStringConvertible {
    let description: String
    init(_ description: String) { self.description = description }
}

func require(_ accepted: Bool, _ message: String) throws {
    guard accepted else { throw ReplayFailure(message) }
}

func disk(_ directory: URL) throws -> [String: Data] {
    let manager = FileManager.default
    let photos = directory.appendingPathComponent("photos")
    var files = ["workspace.json": try Data(contentsOf: directory.appendingPathComponent("workspace.json"))]
    for path in try manager.contentsOfDirectory(at: photos, includingPropertiesForKeys: nil) {
        files["photos/" + path.lastPathComponent] = try Data(contentsOf: path)
    }
    return files
}

@main struct AppleEntryReplay {
    @MainActor static func main() async throws {
        let directory = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
        let repository = try WorkspaceRepository(directory: directory)
        let model = WorkspaceModel(repository: repository)
        await model.open()
        guard let project = await model.createProject(title: "Field site", site: "東京") else {
            throw ReplayFailure("could not create project")
        }
        model.restoreProject(project)
        guard var draft = await model.newDraft(projectID: project) else {
            throw ReplayFailure("could not create draft")
        }

        func screen(_ model: WorkspaceModel, _ draft: EntryDraft, checking: Bool = false) -> EntryScreen {
            model.entryScreen(draft, attaching: false, committing: false, checking: checking)
        }
        try require(!screen(model, draft).control(.commit).enabled, "blank draft could commit")
        let note = String(repeating: "é\n", count: 33_330) + "e\u{301}\n東京"
        try require(note.utf8.count == 100_000, "fixture size")
        let date = Date(timeIntervalSinceReferenceDate: 123456.875)
        draft = model.editEntry(draft, applying: EntryScreen.Field.title.edit("Café 🧪"))
        draft = model.editEntry(draft, applying: EntryScreen.Field.note.edit(note))
        draft = model.editEntry(draft, applying: .category(.issue))
        draft = model.editEntry(draft, applying: .date(date))
        try require(!screen(model, draft).canDismissInteractively, "pending autosaves permitted dismissal")
        try require(!screen(model, draft).control(.checkSavedDraft).enabled, "pending autosaves permitted inspection")
        await model.flush()
        for index in 0..<8 {
            let ids = try await model.addPhoto(Data([0xff, 0xd8, 0xff, UInt8(index), 0xd9]), to: draft)
            draft = model.editEntry(draft, applying: .storedAttachments(ids))
        }
        await model.flush()
        let attachmentIDs = draft.attachmentIDs
        try require(attachmentIDs.count == 8 && !screen(model, draft).control(.photo).enabled, "photo limit")
        try require(screen(model, draft).control(.checkSavedDraft).enabled, "saved action not enabled")
        try require(!screen(model, draft, checking: true).control(.signedCommit).enabled, "check did not gate the signed action")
        try await model.checkSavedDraft(projectID: project, draftID: draft.id)
        let before = try disk(directory)
        try require(before.count == 9, "eight real attachment files")
        let refused = model.editEntry(draft, applying: EntryScreen.Field.note.edit("Invalid\u{0}note\n"))
        await model.flush()
        try require(model.saveError != nil && screen(model, refused).control(.saveDraft).enabled, "failure was not displayed")
        try require(!screen(model, refused).control(.commit).enabled, "invalid note enabled commit")
        let invalidCommit = await model.commit(refused)
        try require(!invalidCommit && (try disk(directory)) == before, "shared refusal changed workspace or photos")
        await repository.close()

        let reopened = try WorkspaceRepository(directory: directory)
        let fresh = WorkspaceModel(repository: reopened)
        await fresh.open()
        guard let restored = fresh.draftEditor?.draft else { throw ReplayFailure("draft not restored") }
        try require(restored.id == draft.id && restored.projectID == project, "restored wrong draft")
        try require(restored.note.utf8.elementsEqual(note.utf8), "note bytes changed on restart")
        try require(restored.category == .issue && restored.occurredAt == date, "typed fields changed")
        try require(restored.attachmentIDs == attachmentIDs, "attachments changed on restart")
        try await fresh.checkSavedDraft(projectID: project, draftID: restored.id)
        let closedDraft = await fresh.keepDraft(restored, close: true)
        try require(closedDraft, "Done save failed")
        try require(fresh.workspace?.restoration.openDraftID == nil, "Done did not clear restoration")
        let commit = await fresh.commit(restored)
        try require(commit, "commit failed")
        guard let saved = fresh.workspace?.entries.first else { throw ReplayFailure("entry not saved") }
        try require(saved.id == draft.id && saved.note.utf8.elementsEqual(note.utf8)
            && saved.attachmentIDs == attachmentIDs && saved.occurredAt == date, "commit content changed")
        let after = try disk(directory)
        try require(before.filter { $0.key != "workspace.json" } == after.filter { $0.key != "workspace.json" }, "photo file changed")
        try require(fresh.workspace?.outbox.filter { $0.kind == .entrySaved }.count == 1, "wrong outbox count")
        await reopened.close()
        print("PASS Apple production WorkspaceModel + EntryScreen: restart, 100000-byte Unicode/LF note, exact ID/date/category, eight photo references/files, blocked inspection/dismissal, shared refusal unchanged, Done and one outbox")
    }
}

