diff --git a/Sources/FieldLogFeatures/EntryScreen.swift b/Sources/FieldLogFeatures/EntryScreen.swift
new file mode 100644
index 0000000000000000000000000000000000000000..53aa2766ef72a74616c0ab7d0d4d46b2fc9a9250
--- /dev/null
+++ b/Sources/FieldLogFeatures/EntryScreen.swift
@@ -0,0 +1,205 @@
+import FieldLogModels
+#if FIELDLOG_SEPARATE_ENTRY_SAVING
+import FieldLogEntrySaving
+#endif
+import Foundation
+import MixerUI
+
+/// The ordinary editor's control identity, availability, and action resolution.
+public struct EntryScreen {
+    public enum Field: String, CaseIterable {
+        case title, note, date
+
+        public func nodeID(_ draftID: UUID) -> String {
+            "entry." + draftID.uuidString.lowercased() + "." + rawValue
+        }
+
+        var actionID: String { "entry." + rawValue + ".change" }
+
+        public var accessibilityID: String {
+            switch self {
+            case .title: EntryEditorForm.titleID
+            case .note: EntryEditorForm.noteID
+            case .date: EntryEditorForm.dateID
+            }
+        }
+
+        public var nativeLabel: String {
+            switch self {
+            case .title: "Entry title"
+            case .note: "Field note"
+            case .date: EntryEditorForm.dateLabel
+            }
+        }
+
+        public func edit(_ value: String) -> EntryEditorForm.Edit {
+            switch self {
+            case .title: .title(value)
+            case .note: .note(value)
+            case .date: .dateText(value)
+            }
+        }
+    }
+
+    public enum Command: String, Sendable {
+        case photo = "entry.photo.select"
+        case cancelPhoto = "entry.photo.cancel"
+        case saveDraft = "entry.saveDraft"
+        case commit = "entry.commit"
+        case checkSavedDraft, signedCommit, done
+    }
+
+    public struct Control {
+        public let label: String
+        public let accessibilityID: String
+        public let enabled: Bool
+
+        func node(_ id: String) -> ModifiedMixerView {
+            MixerUI.Button(id, label, action: id)
+                .accessibilityIdentifier(accessibilityID).disabled(!enabled)
+        }
+    }
+
+    public enum Persistence {
+        case autosave(pending: Bool, unsaved: Bool, checking: Bool)
+        case explicit(saving: Bool, saved: Bool, committed: Bool)
+    }
+
+    public let form: EntryEditorForm
+    let persistence: Persistence
+    let failure: String?
+    let photoBusy: Bool
+    let photoPending: Bool
+    let submitting: Bool
+    let projectID: UUID
+
+    public init(form: EntryEditorForm, projectID: UUID, persistence: Persistence,
+        failure: String?, photoBusy: Bool, photoPending: Bool = false, submitting: Bool = false
+    ) {
+        self.form = form
+        self.projectID = projectID
+        self.persistence = persistence
+        self.failure = failure
+        self.photoBusy = photoBusy
+        self.photoPending = photoPending
+        self.submitting = submitting
+    }
+
+    private var active: Bool {
+        switch persistence {
+        case .autosave: !submitting && !photoBusy
+        case let .explicit(saving, _, committed): !saving && !committed && !photoBusy
+        }
+    }
+
+    public func control(_ command: Command) -> Control {
+        switch (command, persistence) {
+        case (.photo, .autosave):
+            .init(label: "Choose photo", accessibilityID: "entry-photo-select", enabled: !photoBusy && form.hasPhotoCapacity)
+        case (.photo, .explicit):
+            .init(label: "Select photo", accessibilityID: "entry-photo-select", enabled: active && !photoPending && form.hasPhotoCapacity)
+        case (.cancelPhoto, _):
+            .init(label: "Cancel photo selection", accessibilityID: "entry-photo-cancel", enabled: !photoBusy)
+        case (.saveDraft, .autosave):
+            .init(label: "Retry saving draft", accessibilityID: "entry-save-draft", enabled: failure != nil)
+        case (.saveDraft, .explicit(let saving, _, _)):
+            .init(label: saving ? "Saving…" : "Save draft", accessibilityID: "entry-save-draft", enabled: active && form.dateIsValid)
+        case (.commit, .autosave):
+            .init(label: "Save entry", accessibilityID: "save-entry", enabled: active && form.canCommit(projectID: projectID))
+        case (.commit, .explicit(_, _, let committed)):
+            .init(label: committed ? "Saved on device" : "Commit entry", accessibilityID: "entry-commit", enabled: active && form.canCommit(projectID: projectID))
+        case (.checkSavedDraft, _):
+            .init(label: "Check saved draft", accessibilityID: "check-saved-draft", enabled: canInspectSavedDraft)
+        case (.signedCommit, .autosave):
+            .init(label: "Open signed entry commit", accessibilityID: "open-signed-entry-commit", enabled: canInspectSavedDraft)
+        case (.signedCommit, .explicit):
+            .init(label: "Open signed entry commit", accessibilityID: "entry-open-signed-commit", enabled: active && !photoPending)
+        case (.done, _):
+            .init(label: "Done", accessibilityID: "entry-done", enabled: active)
+        }
+    }
+
+    private var canInspectSavedDraft: Bool {
+        guard case let .autosave(pending, unsaved, checking) = persistence else { return false }
+        return active && !pending && !unsaved && !checking
+    }
+
+    public var canDismissInteractively: Bool {
+        guard case let .autosave(pending, unsaved, _) = persistence else { return false }
+        return active && !pending && !unsaved
+    }
+
+    public var status: String? {
+        switch persistence {
+        case let .autosave(pending, unsaved, _):
+            failure ?? (pending || unsaved ? "Saving draft on this device…" : "Draft saved on this device. You can return to it later.")
+        case let .explicit(_, saved, committed):
+            saved && !committed ? "Draft saved on device. Save again to keep later edits." : nil
+        }
+    }
+
+    public enum Action {
+        case edit(EntryEditorForm.Edit)
+        case command(Command)
+    }
+
+    /// Called only after the host routes every event against the original frame.
+    public static func resolve(_ action: RoutedUIAction, draftID: UUID) -> Action? {
+        switch (action.event, action.value) {
+        case (.textChange, .string(let text)):
+            guard let field = Field.allCases.first(where: {
+                $0.nodeID(draftID) == action.nodeID && $0.actionID == action.actionID
+            }) else { return nil }
+            return .edit(field.edit(text))
+        case (.activate, .null) where action.nodeID == action.actionID:
+            switch Command(rawValue: action.actionID) {
+            case .photo: return .command(.photo)
+            case .cancelPhoto: return .command(.cancelPhoto)
+            case .saveDraft: return .command(.saveDraft)
+            case .commit: return .command(.commit)
+            default: break
+            }
+            return EntryCategory.allCases.first { categoryID($0) == action.nodeID }
+                .map { .edit(.category($0)) }
+        default: return nil
+        }
+    }
+
+    private static func categoryID(_ category: EntryCategory) -> String { "entry.category." + category.rawValue }
+
+    private func button(_ command: Command) -> ModifiedMixerView {
+        control(command).node(command.rawValue)
+    }
+
+    public func section(photoMessage: String?, signedCommitAction: String?) -> UINode {
+        let draftID = form.draft.id
+        return MixerUI.Section("entry.fields", title: "Entry") {
+            MixerUI.TextField(Field.title.nodeID(draftID), "Title", value: form.title, action: Field.title.actionID, axis: .vertical)
+                .accessibilityIdentifier(Field.title.accessibilityID).disabled(!active)
+            MixerUI.TextField(Field.note.nodeID(draftID), "Note", value: form.note, action: Field.note.actionID, axis: .vertical)
+                .accessibilityIdentifier(Field.note.accessibilityID).disabled(!active)
+            MixerUI.Text("entry.occurredAt", "Occurred at: " + form.formattedDate)
+            MixerUI.TextField(Field.date.nodeID(draftID), "Date and time (include timezone)", value: form.dateText, action: Field.date.actionID)
+                .accessibilityIdentifier(Field.date.accessibilityID).disabled(!active)
+            MixerUI.Text("entry.date.help", EntryEditorForm.dateTextHelp)
+            if let issue = form.dateIssue { MixerUI.Text("entry.date.error", issue) }
+            button(.photo)
+            if photoPending { button(.cancelPhoto) }
+            if let photoMessage { MixerUI.Text("entry.photo.status", photoMessage) }
+            MixerUI.Text("entry.attachments", "Attachments: \(form.attachmentIDs.count) · References preserved")
+            MixerUI.Text("entry.category", EntryEditorForm.categoryLabel + ": " + form.category.rawValue)
+            for option in EntryEditorForm.categoryOptions {
+                let id = Self.categoryID(option.id)
+                MixerUI.Button(id, option.label, action: id).accessibilityIdentifier(id).disabled(!active)
+            }
+            button(.saveDraft)
+            button(.commit)
+            if let signedCommitAction, control(.signedCommit).enabled {
+                MixerUI.Button(signedCommitAction, control(.signedCommit).label, action: signedCommitAction)
+                    .accessibilityIdentifier(control(.signedCommit).accessibilityID)
+            }
+            if let status { MixerUI.Text("entry.draftSaved", status) }
+            if let failure { MixerUI.Text("entry.failure", String(decoding: failure.utf8.prefix(4000), as: UTF8.self)) }
+        }.uiNode
+    }
+}
