D2/picker/DualPickerReplay.swift.text:
import FieldLogFeatures
import FieldLogModels
import FieldLogStorage
@testable import FieldLogAndroid
import Foundation
import MixerAndroid
import MixerUI

enum ReplayError: Error { case assertion(String), forcedProjection }
func require(_ condition: Bool, _ message: String) throws {
    guard condition else { throw ReplayError.assertion(message) }
}
func rejects(_ message: String, _ effect: () throws -> Void) throws {
    do { try effect() } catch { return }
    throw ReplayError.assertion(message)
}

@MainActor final class Surface: AndroidUINativeSurface {
    let profile = AndroidUIProfile.measuredMultilineLongNotesV4
    var capabilities: AndroidUICapabilities { profile.capabilities }
    var owner: UUID?
    var last: AndroidUIFrame?
    func activate(owner: UUID) throws { try require(self.owner == nil, "surface already active"); self.owner = owner }
    func install(_ frame: AndroidUIFrame) throws {
        try require(frame.owner == owner, "wrong owner delivered")
        let packet = try JSONSerialization.jsonObject(with: frame.packet) as! [String: Any]
        _ = try UIDocument.decode(JSONSerialization.data(withJSONObject: packet["document"]!),
            validator: UIValidator(supportedTextFieldAxes: profile.capabilities.textFieldAxes, textValuePolicy: profile.textValuePolicy))
        last = frame
    }
    func revoke(owner: UUID) { precondition(owner == self.owner); self.owner = nil }
}

@main struct Replay {
    @MainActor static func main() async throws {
        let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
        let appleDir = root.appendingPathComponent("Apple")
        let androidRoot = root.appendingPathComponent("Android")
        let androidDir = androidRoot.appendingPathComponent("FieldLog")
        let origin = try WorkspaceRepository(directory: appleDir)
        let seed = try await origin.transact { workspace in
            let first = try workspace.createProject(title: "North Pier", site: "Harbor")
            let second = try workspace.createProject(title: "South Pump", site: "Café yard")
            for index in 1...23 { try workspace.saveTask(projectID: second, title: "Inspection \(index)", responsible: "A") }
            let note = String(repeating: "é\n", count: 33_330) + "e\u{301}\n東京"
            try workspace.saveDraft(EntryDraft(projectID: second, title: "Saved draft", note: note))
            workspace.restoration.selectedProjectID = first
            workspace.restoration.location = .init(route: .projects, taskPage: 0, draftPage: 0, entryPage: 0, pendingPage: 0)
        }
        await origin.close()
        try FileManager.default.createDirectory(at: androidRoot, withIntermediateDirectories: true)
        try FileManager.default.copyItem(at: appleDir, to: androidDir)
        let first = try unwrap(seed.projects.first)
        let second = try unwrap(seed.projects.last)
        let saved = try unwrap(seed.drafts.first)
        try require(saved.note.utf8.count == 100_000, "V4 note fixture length")
        let appleRepo = try WorkspaceRepository(directory: appleDir)
        let apple = WorkspaceModel(repository: appleRepo, routeProjection: { next in
            if next.route == .settings { throw ReplayError.forcedProjection }
        })
        await apple.open()
        let surface = Surface()
        let android = try await PublicAndroidApplication(surface: surface, selectedProfile: surface.profile.rawValue,
            directory: androidRoot, routeProjection: { next in
                if next.projectID == first.id && next.route == .detail(.tasks) { throw ReplayError.forcedProjection }
            })
        func bytes(_ dir: URL) throws -> Data { try Data(contentsOf: dir.appendingPathComponent("workspace.json")) }
        func send(_ id: String, _ kind: UIEventKind = .activate, _ value: UIValue = .null) throws {
            try android.send(owner: try unwrap(android.host.owner), originalEnvelope: event(id, kind, value))
        }
        func event(_ id: String, _ kind: UIEventKind = .activate, _ value: UIValue = .null) throws -> Data {
            let frame = android.presentation.snapshot
            return try JSONEncoder().encode(UIEventEnvelope(revision: frame.document.revision,
                identity: unwrap(frame.identity(for: id)), event: kind, value: value))
        }
        let firstID = "projects.select." + first.id.uuidString.lowercased()
        let secondID = "projects.select." + second.id.uuidString.lowercased()
        let appleInitial = try unwrap(apple.presentation)
        let before = try bytes(appleDir)
        let original = try event(secondID)
        try require(appleInitial.picker(query: "  cafe  ").rows.map(\.id) == [second.id], "Apple site search")
        try require(appleInitial.picker(query: "pump").rows.map(\.id) == [second.id], "Apple title search")
        try require(appleInitial.picker(query: "").rows.count == 2, "Apple multiple projects")
        let foreign = WorkspacePresentation(restoring: Workspace(), on: .native).navigationScope
        try require(!apple.navigate(.project(second.id), from: foreign), "Apple wrong owner")
        try require(apple.navigate(.settings, from: appleInitial.navigationScope), "Apple projection attempt")
        await apple.flush()
        try require(apple.saveError != nil && apple.presentation?.route == .projects, "Apple projection failure published")
        let appleRefused = try bytes(appleDir)
        try require(appleRefused == before, "Apple refusal changed bytes")

        try rejects("Android wrong owner accepted") { try android.send(owner: UUID(), originalEnvelope: original) }
        try send(firstID)
        do { try await android.settle(); throw ReplayError.assertion("Android forced failure accepted") }
        catch ReplayError.forcedProjection {}
        try require(android.presentation.snapshot.document.root.id == "projects.screen", "Android failure published")
        let androidRefused = try bytes(androidDir)
        try require(androidRefused == before, "Android refusal changed bytes")
        let search = android.presentation.snapshot.identity(for: "projects.search")
        try rejects("V4 granted a long value to picker search") {
            try send("projects.search", .textChange, .string(saved.note))
        }
        try send("projects.search", .textChange, .string("  cafe  "))
        try require(android.presentation.snapshot.identity(for: "projects.search") == search, "Android search identity drift")
        try require(android.presentation.snapshot.identity(for: firstID) == nil &&
            android.presentation.snapshot.identity(for: secondID) != nil, "Android filtering")
        try rejects("Android old picker frame accepted") {
            try android.send(owner: unwrap(android.host.owner), originalEnvelope: original)
        }
        try send(secondID)
        try await android.settle()
        try require(apple.navigate(.project(second.id), from: appleInitial.navigationScope), "Apple selection rejected")
        await apple.flush()
        try require(!apple.navigate(.project(first.id), from: appleInitial.navigationScope), "Apple stale frame")
        try require(apple.presentation?.projectID == second.id && android.presentation.workspace.restoration.selectedProjectID == second.id,
            "wrong project selected")
        try send("tasks.next")
        try await android.settle()
        try require(apple.navigate(.page(.tasks, .next), from: unwrap(apple.presentation).navigationScope), "Apple page rejected")
        await apple.flush()
        let shared = try bytes(appleDir)
        let androidPaged = try bytes(androidDir)
        try require(shared == androidPaged, "platforms stored different project/page bytes")
        try await assertCold(expected: shared, appleDir: appleDir, appleRepo: appleRepo, androidRoot: androidRoot, android: android)

        let appleDraftRepo = try WorkspaceRepository(directory: appleDir)
        let appleDraft = WorkspaceModel(repository: appleDraftRepo)
        await appleDraft.open()
        try require(appleDraft.navigate(.draft(saved.id), from: unwrap(appleDraft.presentation).navigationScope), "Apple draft selection")
        await appleDraft.flush()
        try require(appleDraft.draftEditor?.draft.id == saved.id, "Apple did not select saved draft")
        let nativeDraftBytes = try bytes(appleDir)
        await appleDraftRepo.close()
        let appleDraftColdRepo = try WorkspaceRepository(directory: appleDir)
        let appleDraftCold = WorkspaceModel(repository: appleDraftColdRepo)
        await appleDraftCold.open()
        try require(appleDraftCold.draftEditor?.draft.note.utf8.elementsEqual(saved.note.utf8) == true, "Apple draft bytes")
        let restoredNativeBytes = try bytes(appleDir)
        try require(restoredNativeBytes == nativeDraftBytes, "Apple cold rewrote draft")
        await appleDraftColdRepo.close()

        let androidDraft = try await PublicAndroidApplication(surface: Surface(), selectedProfile: surface.profile.rawValue, directory: androidRoot)
        func draftSend(_ id: String) async throws {
            let snapshot = androidDraft.presentation.snapshot
            let packet = try JSONEncoder().encode(UIEventEnvelope(revision: snapshot.document.revision,
                identity: unwrap(snapshot.identity(for: id)), event: .activate))
            try androidDraft.send(owner: unwrap(androidDraft.host.owner), originalEnvelope: packet)
            try await androidDraft.settle()
        }
        try await draftSend("workspace.entries")
        try await draftSend(ProjectDetailControl.draftID(saved.id))
        try require(androidDraft.presentation.entryState?.draft.id == saved.id, "Android did not select durable draft")
        let androidDraftBytes = try bytes(androidDir)
        await androidDraft.close()
        let androidDraftCold = try await PublicAndroidApplication(surface: Surface(), selectedProfile: surface.profile.rawValue, directory: androidRoot)
