from collections import Counter
import hashlib
import json
from pathlib import Path
import shlex
import subprocess
import sys
import zipfile

root = Path(__file__).resolve().parent
work = root / "work"
app = work / "fieldlog"
baseline = Path(sys.argv[1])
prior = json.loads(baseline.read_text())
pin = "b82cea37d9dc67f8132f89ac066c84b7b1b98ef7"
route = "Sources/FieldLogFeatures/WorkspaceRoute.swift"
picker = "Sources/FieldLogFeatures/ProjectPickerPresentation.swift"
android_prefix = "Integrations/GeneratedReport/"
roles = {route: "logic", picker: "mixed"}

def command(*args):
    return subprocess.check_output(args)

def git(*args):
    return command("git", "-C", app, *args)

def sha(data):
    return hashlib.sha256(data).hexdigest()

def files(path):
    return [Path(shlex.split(line)[0]) for line in path.read_text().splitlines() if line]

def row(path, group, target=None, binary=None):
    relative = path.relative_to(app).as_posix()
    canonical = path.resolve().relative_to(app).as_posix()
    data = path.read_bytes()
    assert data == git("show", ":" + canonical), relative
    if path.is_symlink():
        assert (path.parent / git("show", ":" + relative).decode()).resolve() == path.resolve()
    pinned = prior["rosters"][group].get(relative)
    if pinned:
        original = git("show", pin + ":" + pinned["canonical"])
        assert sha(original) == pinned["sha256"], relative
    role = roles.get(canonical) or pinned["role"]
    result = {"canonical": canonical, "role": role, "physicalLines": len(data.splitlines()), "sha256": sha(data)}
    if binary:
        result.update(target=target, objectSHA256=sha(binary.read_bytes()))
    return relative, result

def demangle(binary, nm):
    return subprocess.check_output(["xcrun", "swift-demangle"], input=command(nm, "--defined-only", binary)).decode()

assert git("cat-file", "-t", pin).strip() == b"tree" and pin == prior["sourceTree"]
tree = git("write-tree").decode().strip()
apple = work / "ios-build/Build/Intermediates.noindex/FieldLog.build/Debug-iphonesimulator"
apple_product = work / "ios-build/Build/Products/Debug-iphonesimulator/FieldLog.app/FieldLog"
apple_links = files(apple / "FieldLog.build/Objects-normal/arm64/FieldLog.LinkFileList")
apple_inputs = {}
for roster in sorted(apple.glob("*/Objects-normal/arm64/*.SwiftFileList")):
    target = roster.stem
    if target != "FieldLog":
        assert target + ".o" in {obj.name for obj in apple_links}, target
    links = {obj.name: obj for obj in files(roster.with_suffix(".LinkFileList"))}
    for path in files(roster):
        binary = links[path.stem + ".o"]
        if target == "FieldLog":
            assert binary in apple_links
        name, value = row(path, "appleSwift", target, binary)
        apple_inputs[name] = value

android = work / "android-build/aarch64-unknown-linux-android28/release"
android_product = android / "libAppAndroid.so"
elf_nm = Path.home() / ".swiftpm/swift-sdks/swift-6.3.3-RELEASE_android.artifactbundle/swift-android/android-ndk-r27d/toolchains/llvm/prebuilt/darwin-x86_64/bin/llvm-nm"
android_links = set(files(android / "AppAndroid.product/Objects.LinkFileList"))
android_inputs = {}
conditional = {"Integrations/GeneratedReport/Sources/FieldLogFeatures/" + name for name in ("EntryEditorAppleHost.swift", "TaskEditorAppleFieldsHost.swift")}
conditional |= {android_prefix + "Sources/FieldLogAndroid/" + name for name in ("SignedChecklist.swift", "SignedEntryCommit.swift")}
for roster in sorted(android.glob("FieldLog*.build/sources")):
    target = roster.parent.name.removesuffix(".build")
    for path in files(roster):
        relative = path.relative_to(app).as_posix()
        binary = roster.parent / (path.name + ".o")
        assert binary in android_links, relative
        if relative in conditional:
            assert all(line.endswith(b" __swift_reflection_version") for line in
                       command(elf_nm, "--defined-only", "--extern-only", binary).splitlines()), relative
            conditional.remove(relative)
        else:
            name, value = row(path, "androidSwift", target, binary)
            android_inputs[name] = value
assert not conditional
assert apple_inputs.keys() == prior["rosters"]["appleSwift"].keys() | {route}
assert android_inputs.keys() == prior["rosters"]["androidSwift"].keys() | {android_prefix + route, android_prefix + picker}
for path in (picker, route):
    assert apple_inputs[path]["canonical"] == android_inputs[android_prefix + path]["canonical"] == path

apple_symbols = demangle(apple_product, "nm")
android_symbols = demangle(android_product, elf_nm)
symbols = {}
for name, listing, suffixes in (
    ("apple", apple_symbols, ("ProjectPickerPresentation.rows.getter", "WorkspacePresentation.navigate(", "WorkspaceModel.navigate(")),
    ("android", android_symbols, ("ProjectPickerPresentation.document(", "WorkspacePresentation.navigate(", "ProjectPresentation.sendBatch(")),
):
    symbols[name] = {}
    for suffix in suffixes:
        matches = [line for line in listing.splitlines() if suffix in line and " T " in line]
        if not matches:
            matches = [line for line in listing.splitlines() if suffix in line and " t " in line]
        assert matches, (name, suffix)
        symbols[name][suffix] = matches[0]

assert command("xcrun", "lipo", "-archs", apple_product).strip() == b"arm64"
assert "platform 7" in command("xcrun", "otool", "-l", apple_product).decode()
assert "ARM aarch64" in command("file", "-b", android_product).decode()

def by_content(rows):
    return {value["sha256"]: (value["role"], value["physicalLines"]) for value in rows.values()}

def totals(rows):
    count = Counter({"ui": 0, "logic": 0, "mixed": 0})
    for role, lines in rows.values():
        count[role] += lines
    return {"files": len(rows), "total": sum(count.values()), "byRole": dict(count)}

a, d = map(by_content, (apple_inputs, android_inputs))
assert all(a[key] == d[key] for key in a.keys() & d.keys())
shared = {key: a[key] for key in a.keys() & d.keys()}
counts = {label: totals(group) for label, group in (
    ("appleSwift", a), ("androidSwift", d),
    ("sharedSwift", shared), ("swiftUnion", a | d)
)}
for label, union in (("sharedSwiftPercent", "swiftUnion"),):
    counts[label] = 100 * counts["sharedSwift"]["total"] / counts[union]["total"]
report = {
    "sourceTree": tree, "baselineTree": pin, "countingUnit": "Identical physical source files, admitted by actual compile and link rosters, broken out by whole-file role. Mixed files can include platform-specific branches.",
    "baseline": {k: prior["candidate"][k] for k in counts}, "candidate": counts,
    "symbols": symbols,
    "products": {name: sha(path.read_bytes()) for name, path in (("appleSimulatorApp", apple_product), ("androidAppAndroid", android_product))},
    "rosters": {"appleSwift": apple_inputs, "androidSwift": android_inputs},
}
(root / "linked-membership.json").write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
print(json.dumps(counts, indent=2))

