+import FieldLogModels
+import Foundation
+import MixerUI
+
+extension WorkspacePresentation {
+  public enum NavigationSurface: Sendable {
+    case native, android
+
+    fileprivate var detail: Detail { self == .native ? .nativeList : .tasks }
+  }
+
+  public enum NavigationIntent {
+    case project(UUID?)
+    case projects
+    case projectTab
+    case detail(Detail)
+    case pendingChanges
+    case settings
+    case page(ProjectDetailPage.Records, ProjectDetailPage.Direction)
+    case draft(UUID)
+  }
+
+  public struct NavigationScope: Equatable, Sendable {
+    fileprivate let owner: UUID
+    fileprivate let revision: UInt64
+    fileprivate let generation: UUID
+  }
+
+  public var navigationScope: NavigationScope {
+    NavigationScope(owner: workspace.id, revision: workspace.revision, generation: navigationGeneration)
+  }
+
+  public init(restoring workspace: Workspace, on surface: NavigationSurface) {
+    let saved = workspace.restoration
+    let project = saved.selectedProjectID.flatMap { id in workspace.projects.first { $0.id == id } }
+      ?? (surface == .android ? workspace.projects.first : nil)
+    let draft = workspace.restoredDraft(in: surface == .android ? project?.id : nil)
+    let location = saved.location
+    let route: Route = switch location?.route {
+    case .projects: .projects
+    case .pendingChanges: .pendingChanges
+    case .settings: surface == .native ? .settings : project.map { _ in .detail(.tasks) } ?? .projects
+    case .entries where surface == .android && project != nil: .detail(.entries)
+    default:
+      project.map { _ in
+        .detail(surface == .android && location == nil && draft != nil ? .entries : surface.detail)
+      } ?? .projects
+    }
+    var pages = ProjectDetailPages()
+    pages.tasks = max(0, location?.taskPage ?? 0)
+    pages.drafts = max(0, location?.draftPage ?? 0)
+    pages.entries = max(0, location?.entryPage ?? 0)
+    self.init(workspace: workspace, projectID: project?.id, route: route, pages: pages,
+      pendingPage: location?.pendingPage ?? 0)
+    clampPendingPage()
+    selectDraft(draft)
+  }
+
+  public func picker(query: String) -> ProjectPickerPresentation {
+    ProjectPickerPresentation(in: workspace, query: query)
+  }
+
+  public func navigate(_ intent: NavigationIntent, from scope: NavigationScope,
+    on surface: NavigationSurface) throws -> NavigationPlan
+  {
+    guard scope == navigationScope else { throw FieldLogError.staleRevision }
+    var next = self
+    switch intent {
+    case let .project(id):
+      guard id == nil || workspace.projects.contains(where: { $0.id == id }),
+        surface == .native || (route == .projects && id != nil)
+      else { throw FieldLogError.missingRecord }
+      next.selectProject(id, detail: surface.detail)
+      if surface == .native && (route == .pendingChanges || route == .settings) { next.show(route) }
+      if projectID != id { next.selectDraft(nil) }
+    case .projects:
+      next.show(.projects)
+    case .projectTab:
+      next.show(projectID == nil ? .projects : .detail(surface.detail))
+    case let .detail(detail):
+      guard projectID != nil else { throw FieldLogError.missingRecord }
+      next.show(.detail(detail))
+    case .pendingChanges:
+      next.show(.pendingChanges)
+    case .settings:
+      guard surface == .native else { throw FieldLogError.missingRecord }
+      next.show(.settings)
+    case let .page(records, direction):
+      guard next.turnDetail(records, direction) else { throw FieldLogError.missingRecord }
+    case let .draft(id):
+      guard let draft = workspace.drafts.first(where: { $0.id == id }),
+        (surface == .native && route == .pendingChanges) || draft.projectID == projectID
+      else { throw FieldLogError.missingRecord }
+      next.selectDraft(draft)
+      if surface == .android { next.show(.detail(.entries)) }
+    }
+    return navigationPlan(to: next, openDraft: next.draftEditor?.draft.id != draftEditor?.draft.id)
+  }
+
+  public func navigationIntent(for resolution: DetailResolution) -> NavigationIntent? {
+    switch resolution {
+    case .control(.showTasks): .detail(.tasks)
+    case .control(.showEntries): .detail(.entries)
+    case .control(.queue): .pendingChanges
+    case let .page(records, direction): .page(records, direction)
+    case let .draft(draft): .draft(draft.id)
+    default: nil
+    }
+  }
+
+  public func navigationPlan(to next: Self, openDraft: Bool = false) -> NavigationPlan {
+    var restoration = workspace.restoration
+    restoration.selectedProjectID = next.projectID
+    if openDraft { restoration.openDraftID = next.draftEditor?.draft.id }
+    let route: Restoration.Location.Route = switch next.route {
+    case .projects: .projects
+    case .detail(.entries): .entries
+    case .detail: .tasks
+    case .pendingChanges: .pendingChanges
+    case .settings: .settings
+    }
+    restoration.location = .init(route: route, taskPage: next.pages.tasks, draftPage: next.pages.drafts,
+      entryPage: next.pages.entries, pendingPage: next.pendingPage)
+    return NavigationPlan(source: navigationScope, destination: next, restoration: restoration)
+  }
+
+  public struct NavigationPlan: Sendable {
+    public let source: NavigationScope
+    public let destination: WorkspacePresentation
+    fileprivate let restoration: Restoration
+    public var revision: UInt64 { source.revision }
+    public var needsWrite: Bool { destination.workspace.restoration != restoration }
+
+    public func apply(to workspace: inout Workspace) throws {
+      guard workspace.id == source.owner, workspace.revision == source.revision else {
+        throw FieldLogError.staleRevision
+      }
+      workspace.restoration = restoration
+    }
+
+    public func projected(in workspace: Workspace) -> WorkspacePresentation {
+      var next = destination
+      next.updateWorkspace(workspace)
+      return next
+    }
+  }
+}
