"""Apply exact, diagnostic-only edits to a separate copy of the admitted Java source."""
from pathlib import Path
import shutil
import sys

source, target = map(Path, sys.argv[1:])
shutil.copytree(source, target, ignore=shutil.ignore_patterns("evidence"))


def edit(file, changes):
    path = target / file
    data = path.read_text()
    for before, after in changes:
        if data.count(before) != 1:
            raise ValueError(f"Expected one diagnostic insertion in {file}: {before!r}")
        data = data.replace(before, after, 1)
    path.write_text(data)


