#!/usr/bin/env python3
"""Root-only Android D2 title trace on an owned, fresh API 36 emulator."""
import argparse
import json
from pathlib import Path
import re

from original_replay import EDIT_TEXT, Replay
from owned_command import UnknownCustody
from preflight import APK, PACKAGE, digest, require

HINT = "What needs to happen?"
TITLES = ["Valve", "Gauge", *(f"Inspection {i}" for i in range(3, 22))]


class EditorReplay(Replay):
    def __init__(self, args):
        super().__init__(args)
        self.pid = None
        self.attempts = []

    def write_json(self, name, value):
        self.save(name, (json.dumps(value, indent=2) + "\n").encode())

    def launch(self):
        super().launch()
        pid = self.shell("pidof", PACKAGE).decode().strip()
        require(pid.isascii() and pid.isdecimal() and int(pid) > 0, "Expected a single FieldLog PID")
        self.pid = pid
        self.write_json("trace-process.json", {"pid": pid, "serial": self.serial, "transport": self.transport})

    def read_echo(self):
        return {
            "xml": f"ui-{self.counter:04d}.xml",
            "titleFields": [
                {"text": n["text"], "focused": n["focused"], "enabled": n["enabled"]}
                for n in self.nodes
                if n.get("class") == EDIT_TEXT and n.get("content-desc") == HINT
            ],
        }

    def expect(self, label, **options):
        if not self.attempts or label != self.attempts[-1]["title"] or options != {"field": True, "swipes": 0}:
            return super().expect(label, **options)
        attempt = self.attempts[-1]
        attempt["focusedBeforeInput"] = self.read_echo()
        try:
            return super().expect(label, **options)
        except ValueError:
            attempt["phase"] = "first-echo-mismatch"
            raise
        finally:
            # Called immediately after the original driver's one echo check.
            # The extra hierarchy reads on mismatch happen only after this check.
            attempt["firstEcho"] = self.read_echo()

    def task(self, title, *, first=False, visible=True):
        attempt = {"title": title, "phase": "started"}
        self.attempts.append(attempt)
        try:
            super().task(title, first=first, visible=visible)
            attempt["phase"] = "saved"
        finally:
            self.write_json("task-attempts.json", self.attempts)

    def exercise_editor(self):
        super().exercise(short=True)
        for title in TITLES[2:]:
            self.task(title, visible=False)
        self.expect("Page 2 of 2 · Tasks 21–21 of 21", toward_top=False)
        self.expect("21. Inspection 21 · Not completed", toward_top=False)
        return self.verify_saved(TITLES, "after-repeated-saves")

    def verify_saved(self, titles, name):
        workspace, sha = self.disk(name)
        _, _, events = self.summary(workspace, [
            "projectCreated", "taskSaved", "taskSaved", "taskSaved", "taskOrderChanged",
            *(["taskSaved"] * (len(titles) - 2)),
        ])
        tasks = sorted(workspace["tasks"], key=lambda task: task["position"])
        require([t["title"] for t in tasks] == [titles[1], titles[0], *titles[2:]], "Exact durable title/order changed")
        require([e["recordID"] for e in events[5:]] == [t["id"] for t in tasks[2:]], "Task save record IDs differ")
        return {"workspaceSHA256": sha, "confirmedSaves": len(titles)}

    def observe_after_failure(self):
        if not self.attempts or self.attempts[-1]["phase"] != "first-echo-mismatch":
            return
        attempt = self.attempts[-1]
        attempt["laterEchoes"] = []
        for _ in range(2):
            self.snapshot()
            attempt["laterEchoes"].append(self.read_echo())
            self.write_json("task-attempts.json", self.attempts)
        confirmed = [row["title"] for row in self.attempts if row["phase"] == "saved"]
        if len(confirmed) >= 2:
            self.write_json("before-unsaved-title-result.json",
                            self.verify_saved(confirmed, "before-unsaved-title"))

    def collect_trace(self):
        if self.pid is None:
            return
        argv = ("logcat", "-d", "--pid", self.pid, "-v", "threadtime", "-s", "D2EditorTrace:I", "*:S")
        trace = self.adb(*argv, read_closed=True)
        self.save("editor.log", trace)
        require(b"D2EditorTrace" in trace and b"surface install returned" in trace,
                "No instrumented surface trace was collected")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--signed", required=True, type=Path)
    parser.add_argument("--adb-port", required=True, type=int)
    parser.add_argument("--transport-id", required=True, type=int)
    parser.add_argument("--serial", required=True)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--seconds", default=540, type=int)
    args = parser.parse_args()
    require(1024 <= args.adb_port <= 65535 and args.adb_port != 5037 and args.transport_id > 0
            and re.fullmatch(r"emulator-\d+", args.serial) and 30 <= args.seconds <= 600,
            "Explicit private ADB server and owned emulator transport required")
    args.output.mkdir()
    replay = EditorReplay(args)
    try:
        replay.admit(APK, args.signed, False)
        replay.shell("run-as", PACKAGE, "test", "!", "-e", "files/FieldLog/workspace.json")
        summary = replay.exercise_editor()
        replay.installed(digest(args.signed))
    except UnknownCustody:
        raise
    except Exception as original:
        replay.write_json("failure.json", {"type": type(original).__name__, "message": str(original)})
        try:
            replay.observe_after_failure()
        except UnknownCustody:
            raise
        except Exception as observation:
            replay.write_json("observation-failure.json", {"message": str(observation)})
        raise
    finally:
        # Set in adb() before an UNKNOWN return. Never collect or remove
        # further device evidence if a command lost custody.
        if not (args.output / "HOLD.txt").exists():
            try:
                replay.collect_trace()
            finally:
                if replay.touched and not (args.output / "HOLD.txt").exists():
                    replay.adb("shell", "rm", "-f", replay.xml, read_closed=True)
    replay.write_json("result.json", summary)
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()
